INSERT INTO `param_dependencies` VALUES (1,'初撑力系数','0.8',NULL,NULL,'初撑力与工作阻力的比值','力学参数','重复参数: 与setting_ratio同义且代码未引用, 弃用保留(W25-D6)','2026-07-30 08:23:22'),(3,'采高裕量','0.3',NULL,NULL,'支架最大采高与煤层厚度的安全差值','安全参数','经验规则(支架最大高度应高于煤层厚度),待文献佐证','2026-07-30 08:23:22'),(4,'eta','0.9',NULL,NULL,'立柱机械效率','计算参数','《煤矿支护手册》立柱机械效率经验值','2026-08-06 07:48:30'),(5,'safety_factor','1.2',NULL,NULL,'支护强度安全系数','计算参数','经验规则,待文献佐证','2026-08-06 07:48:30'),(6,'k1','8',NULL,'顶板岩厚度系数(大采高取8)',NULL,NULL,'经验规则(大采高顶板岩厚系数),待文献佐证','2026-08-13 09:06:09'),(7,'rock_gamma','25','kN/m3','顶板岩层重力密度',NULL,NULL,'工程岩体力学常用值(砂岩容重典型25kN/m3)','2026-08-13 09:06:09'),(8,'beam_length','5.2','m','顶梁长度(两柱式默认)',NULL,NULL,'默认值,实测分布以support_models统计为准(W25-D4)','2026-08-13 09:06:09'),(9,'roof_end_distance','0.7','m','梁端距',NULL,NULL,'默认值,实测分布以support_models统计为准(W25-D4)','2026-08-13 09:06:09'),(10,'center_distance','2.05','m','支架中心距(默认)',NULL,NULL,'默认值,实测分布以support_models统计为准(W25-D4)','2026-08-13 09:06:09'),(12,'setting_ratio','0.7',NULL,'初撑力/工作阻力比(0.6~0.85)',NULL,NULL,'MT/T 556-1996 液压支架设计规范(初撑力为工作阻力0.6~0.8)','2026-08-13 09:06:09'),(14,'pump_pressure','31.5','MPa','乳化液泵站额定压力(常用档)',NULL,'液压参数','经验规则,待文献佐证','2026-09-10 05:14:56'),(15,'q_thin_min','0.3','MPa','薄煤层支护强度下限',NULL,'支护参数','经验规则,待文献佐证','2026-09-10 05:14:56'),(16,'q_mid_min','0.6','MPa','中厚煤层支护强度下限',NULL,'支护参数','经验规则,待文献佐证','2026-09-10 05:14:56'),(17,'q_large_min','1.0','MPa','大采高支护强度下限',NULL,'支护参数','经验规则,待文献佐证','2026-09-10 05:14:56'),(18,'height_margin_ratio','0.1',NULL,'支架最大高度超出采高的比例下限',NULL,'安全参数','经验规则,待文献佐证','2026-09-10 05:14:56');
/*!40000 ALTER TABLE `param_dependencies` ENABLE KEYS */;
